/* eslint-disable */
/* global WebImporter */
/**
 * Parser for cards-numbered. Base: cards.
 * Source: https://us.etrade.com/what-we-offer/our-accounts/brokerage-account
 * Grid of numbered feature cards. Each card: an ordinal (generated by the block —
 * NOT included as content), an H3 heading, a description, and a "Learn more" link.
 * decorate() expects one row per card, single column:
 *   [ heading, description paragraph(s), link ]
 */
export default function parse(element, { document }) {
  // Each card is a .card-container (pricing-card styling in source).
  const cards = Array.from(element.querySelectorAll('.card-container'));

  const cells = [];
  cards.forEach((card) => {
    // Heading (H3). Ordinal number lives in p.numeric-stats-lg — deliberately excluded.
    const heading = card.querySelector('.card-text-group h3, h3');
    // Description text.
    const description = card.querySelector('.card-text-group .text-default, .text-default');
    // "Learn more" link.
    const link = card.querySelector('.card-btn-group a, a.btn-link, a');

    const contentCell = [];
    if (heading) contentCell.push(heading);
    if (description) contentCell.push(description);
    if (link) contentCell.push(link);

    if (contentCell.length) cells.push([contentCell]);
  });

  if (!cells.length) {
    element.replaceWith(...element.childNodes);
    return;
  }

  const block = WebImporter.Blocks.createBlock(document, { name: 'cards-numbered', cells });
  element.replaceWith(block);
}
